<script setup lang="ts">
import {ref,reactive,onMounted} from 'vue';import {useRoute} from 'vue-router';import {admin,money,date,mutationKey} from '../../../shared/api';import type {Order,Page} from '../../../shared/types';import type {PickupLookup} from '../../../shared/adminTypes';import {useLoad} from '../../../shared/useLoad';import {ElMessage,ElMessageBox} from 'element-plus'
const route=useRoute(),result=ref<Page<Order>>(),detail=ref<Order>(),detailOpen=ref(false),pickupOpen=ref(false),code=ref(''),lookup=ref<PickupLookup>(),verified=ref(false),query=reactive({orderNo:'',status:'pending_confirmation'}),key=mutationKey(),{loading,error,run}=useLoad()
const load=(page=1)=>run(async()=>{result.value=await admin('GET','/admin/orders',undefined,{orderNo:query.orderNo||undefined,status:query.status||undefined,page,pageSize:10})})
const view=(id:string)=>run(async()=>{detail.value=await admin('GET',`/admin/orders/${id}`);detailOpen.value=true})
const find=()=>run(async()=>{lookup.value=undefined;verified.value=false;lookup.value=await admin('POST','/admin/pickups/lookup',{pickupCode:code.value})})
const deliver=()=>run(async()=>{const body={confirmationId:lookup.value?.buyerConfirmation?.id,pickupCode:code.value,quarantineVerified:verified.value};const path=`/admin/orders/${lookup.value!.order.id}/pickup`;await admin('POST',path,body,undefined,key(path,body));ElMessage.success('交付已完成，自提码已失效');pickupOpen.value=false;lookup.value=undefined;result.value=await admin('GET','/admin/orders',undefined,{orderNo:query.orderNo||undefined,status:query.status||undefined,page:1,pageSize:10})})
// 每次操作携带幂等键，网络重试不会重复完成交付。
async function appointmentAction(action:'confirm'|'cancel'|'complete') {
 if(!detail.value)return
 let body:Record<string,unknown>={}
 try {
  if(action==='cancel') {const result=await ElMessageBox.prompt('请填写取消原因，买家可以查看。','取消预约',{inputValidator:value=>!!value?.trim()||'请填写原因'});body={reason:result.value.trim()}}
  if(action==='complete') {await ElMessageBox.confirm(`确认已收到 ${money(detail.value.amount)}，已核验有效检疫证明，且已将宠物交付给预约本人？此操作将标记宠物已售出。`,'登记到店付款并交付',{confirmButtonText:'已收款并交付',cancelButtonText:'返回核实',type:'warning'});body={paymentReceived:true,deliveryConfirmed:true,quarantineVerified:true}}
 } catch {return}
 await run(async()=>{const path=`/admin/orders/${detail.value!.id}/appointment/${action}`;detail.value=await admin('POST',path,body,undefined,key(path,body));ElMessage.success('预约状态已更新');result.value=await admin('GET','/admin/orders',undefined,{orderNo:query.orderNo||undefined,status:query.status||undefined,page:1,pageSize:10})})
}
onMounted(()=>{void load();pickupOpen.value=route.query.pickup==='1'})
</script>
<template><div class="section-title"><div><p class="eyebrow">ORDERS & PICKUP</p><h2>查看预约，安排到店。</h2></div><el-button type="primary" size="large" @click="pickupOpen=true">历史订单核销</el-button></div><form class="toolbar" @submit.prevent="load()"><el-input v-model="query.orderNo" placeholder="搜索订单号" clearable/><el-select v-model="query.status" placeholder="全部状态" clearable @change="load()"><el-option v-for="item in [['pending_confirmation','预约待确认'],['reservation_confirmed','已确认待到店'],['expired','预约已过期'],['pending_paid','历史待付款'],['paid','待自提'],['completed','已完成'],['refunding','退款中'],['refunded','已退款'],['cancelled','已取消']]" :key="item[0]" :value="item[0]" :label="item[1]"/></el-select><el-button native-type="submit" :loading="loading">查询</el-button></form><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="table-panel"><el-table :data="result?.items||[]" v-loading="loading"><el-table-column label="订单 / 宠物" min-width="230"><template #default="{row}">{{row.orderNo}}<p class="small" style="margin:4px 0 0">{{row.product.name}} · {{row.product.breed}}</p></template></el-table-column><el-table-column prop="contactName" label="联系人" min-width="100"/><el-table-column prop="contactPhone" label="手机号" min-width="135"/><el-table-column label="到店时间" min-width="150"><template #default="{row}">{{date(row.appointment?.visitAt)}}</template></el-table-column><el-table-column label="金额" min-width="130"><template #default="{row}">{{money(row.amount)}}</template></el-table-column><el-table-column prop="statusText" label="状态" min-width="110"/><el-table-column label="操作" width="120"><template #default="{row}"><el-button link type="primary" @click="view(row.id)">查看详情</el-button></template></el-table-column></el-table></div><div class="pagination"><el-pagination v-if="result" layout="prev,pager,next" :total="result.total" :current-page="result.page" :page-size="10" @current-change="load"/></div><el-drawer v-model="detailOpen" title="预约 / 订单详情" size="540px"><template v-if="detail"><h3>{{detail.orderNo}}</h3><el-tag>{{detail.statusText}}</el-tag><div class="order-card"><img :src="detail.product.coverUrl" :alt="detail.product.name"><div><h3>{{detail.product.name}} · {{detail.product.breed}}</h3><p class="amount">{{money(detail.amount)}}</p></div></div><el-descriptions :column="1"><el-descriptions-item label="联系人">{{detail.contactName}} · {{detail.contactPhone||detail.contactPhoneMasked}}</el-descriptions-item><el-descriptions-item v-if="detail.appointment" label="预约到店">{{date(detail.appointment.visitAt)}}（北京时间）</el-descriptions-item><el-descriptions-item v-if="detail.appointment" label="当前截止">{{date(detail.expiresAt)}}</el-descriptions-item><el-descriptions-item v-if="detail.cancelReason" label="取消原因">{{detail.cancelReason}}</el-descriptions-item><el-descriptions-item label="创建时间">{{date(detail.createdAt)}}</el-descriptions-item><el-descriptions-item label="付款时间">{{date(detail.paidAt)}}</el-descriptions-item><el-descriptions-item label="交付时间">{{date(detail.completedAt)}}</el-descriptions-item><el-descriptions-item label="买家备注">{{detail.remark||'无'}}</el-descriptions-item></el-descriptions><el-button v-if="detail.status==='paid'" type="primary" @click="detailOpen=false;pickupOpen=true">输入买家自提码办理核销</el-button><div v-if="detail.appointment" class="stack"><p>预约确认不代表收款。实际收款、核验证明并交付后，才能登记完成。</p><el-button v-if="detail.status==='pending_confirmation'" type="primary" :loading="loading" @click="appointmentAction('confirm')">确认到店预约</el-button><el-button v-if="detail.status==='reservation_confirmed'" type="primary" :loading="loading" @click="appointmentAction('complete')">已到店付款并交付</el-button><el-button v-if="['pending_confirmation','reservation_confirmed'].includes(detail.status)" type="danger" plain :loading="loading" @click="appointmentAction('cancel')">取消预约</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/></template></el-drawer><el-dialog v-model="pickupOpen" title="到店核销" width="600px"><form class="toolbar" @submit.prevent="find"><el-input v-model="code" placeholder="输入买家出示的8位自提码" maxlength="8" aria-label="自提码"/><el-button native-type="submit" :loading="loading" :disabled="code.length!==8">查询订单</el-button></form><template v-if="lookup"><div class="order-card"><img :src="lookup.order.product.coverUrl" :alt="lookup.order.product.name"><div><h3>{{lookup.order.product.name}}</h3><p>{{lookup.contactName}} · {{lookup.contactPhoneMasked}}</p></div></div><el-alert :type="lookup.pickupAllowed?'success':'warning'" :title="lookup.pickupAllowed?'买家本人确认已完成':lookup.blockedReason||'等待买家确认'" :closable="false"/><p v-if="lookup.buyerConfirmation">确认时间：{{date(lookup.buyerConfirmation.confirmedAt)}}<br>有效截止：{{date(lookup.buyerConfirmation.validUntil)}}</p><el-checkbox v-model="verified" :disabled="!lookup.pickupAllowed">已核对当前个体与有效检疫证明</el-checkbox></template><el-alert v-if="error" :title="error" type="error" :closable="false"/><template #footer><el-button @click="pickupOpen=false">关闭</el-button><el-button type="primary" :loading="loading" :disabled="!lookup?.pickupAllowed||!verified" @click="deliver">确认交付并核销</el-button></template></el-dialog></template>
